/**
 * Runtime support for vecDSL programs generated for Elasticsearch, through the official @elastic/elasticsearch client.
 * Generated by vecDSL 7. Do not edit.
 *
 * Every request body (index mappings, queries, aggregations, painless scripts with their params) is built by the generator
 * and arrives here as a JSON value, identical in the Python, TypeScript and Java programs; this module sends it with
 * client.transport.request and shapes the answer: hits become records with the key, the score in the canonical form of
 * vecDSL and the returned fields; hybrid search fuses its legs here (the rrf and linear retrievers need an enterprise
 * license). Writes go through the _bulk API with refresh=true, so the next statement sees them.
 */

import { readFileSync } from "node:fs";
import { Client as Elasticsearch, errors } from "@elastic/elasticsearch";

export const SDK_PACKAGE = "{{sdk.typescript.package}}";
export const SDK_VERSION = "{{sdk.typescript.version}}";

const DIGITS = 6;
const BATCH = 500;
const KEEP_ALIVE = "1m";

type Json = unknown;
type Doc = Record<string, unknown>;
type Hit = { _id: string; _score: number; _source?: Doc; highlight?: unknown; _explanation?: unknown; fields?: Record<string, unknown[]>; inner_hits?: Record<string, { hits: { hits: Hit[] } }>; found?: boolean };
type Form = { kind: string; dims?: number };
type Bounds = { min?: number; max?: number };
type Mmr = { field: string; kind: string; lambda: number; window: number };

export class UnsupportedFeature extends Error {}

export class ElasticsearchFailure extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

/** The Elasticsearch client of one program; credentials come from the environment only. */
export class Client {
  readonly es: Elasticsearch;

  constructor(readonly url: string, user: string, passwordVariable: string, apiKeyVariable: string | undefined, timeoutSeconds: number) {
    if (/\/\/[^/]*@/.test(url)) {
      throw new Error("the server URL must not contain credentials; set them in the environment");
    }
    const apiKey = apiKeyVariable === undefined ? undefined : process.env[apiKeyVariable];
    let auth: { apiKey: string } | { username: string; password: string };
    if (apiKey) {
      auth = { apiKey };
    } else {
      const password = process.env[passwordVariable];
      if (password === undefined) {
        throw new Error(`environment variable ${passwordVariable} is not set (the password of user ${user})`);
      }
      auth = { username: user, password };
    }
    this.es = new Elasticsearch({ node: url, auth, requestTimeout: timeoutSeconds * 1000, maxRetries: 0 });
  }

  async close(): Promise<void> {
    await this.es.close();
  }
}

export interface ConnectOptions {
  url: string;
  user?: string;
  passwordVariable?: string;
  apiKeyVariable?: string;
  timeoutSeconds?: number;
}

export async function connect(options: ConnectOptions): Promise<Client> {
  return new Client(options.url, options.user ?? "elastic", options.passwordVariable ?? "VECDSL_ELASTICSEARCH_PASSWORD",
    options.apiKeyVariable, options.timeoutSeconds ?? 30);
}

/** Result values in one form for every host language: floats rounded, integral numbers as integers. */
function value(item: Json): Json {
  if (typeof item === "number") {
    return Number.isFinite(item) ? Number(item.toFixed(DIGITS)) + 0 : item;
  }
  if (Array.isArray(item)) {
    return item.map(value);
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item as Doc).map(([key, entry]) => [key, value(entry)]));
  }
  return item;
}

function reason(body: unknown): string {
  const error = (body as { error?: { root_cause?: { type?: string; reason?: string }[]; type?: string; reason?: string } } | undefined)?.error;
  if (error && typeof error === "object") {
    const cause = error.root_cause?.[0] ?? error;
    return `${cause.type}: ${cause.reason}`;
  }
  return JSON.stringify(body ?? null).slice(0, 500);
}

function queryString(params?: Record<string, unknown>): Record<string, string> | undefined {
  if (params === undefined) {
    return undefined;
  }
  return Object.fromEntries(Object.entries(params).map(([key, item]) => [key, String(item)]));
}

async function send(client: Client, method: string, path: string, params?: Record<string, unknown>, body?: Json, ignore: number[] = [],
  ndjson = false): Promise<any> {
  try {
    const request = ndjson
      ? { method, path, querystring: queryString(params), bulkBody: body as Doc[] }
      : { method, path, querystring: queryString(params), body: body as Doc | undefined };
    return await client.es.transport.request(request);
  } catch (error) {
    if (error instanceof errors.ResponseError) {
      if (ignore.includes(error.meta.statusCode ?? 0)) {
        return null;
      }
      throw new ElasticsearchFailure(`${method} ${path} failed with status ${error.meta.statusCode}: ${reason(error.meta.body)}`);
    }
    if (error instanceof errors.ConnectionError || error instanceof errors.TimeoutError) {
      throw new ElasticsearchFailure(`cannot reach Elasticsearch at ${client.url} within the request timeout: ${error.message}`);
    }
    throw error;
  }
}

function select(item: any, path?: string[]): any {
  for (const key of path ?? []) {
    item = item == null ? null : item[key];
  }
  return item ?? null;
}

export interface RequestArgs {
  method: string;
  path: string;
  params?: Record<string, unknown>;
  body?: Json;
  select?: string[];
  wrap?: string;
  ignore?: number[];
}

/** One request; select picks a member of the answer, wrap names it in a one-entry object. */
export async function request(client: Client, args: RequestArgs): Promise<Json> {
  const result = value(select(await send(client, args.method, args.path, args.params, args.body, args.ignore ?? []), args.select));
  return args.wrap === undefined ? result : { [args.wrap]: result };
}

export async function exists(client: Client, args: { path: string }): Promise<boolean> {
  return (await send(client, "HEAD", args.path)) === true;
}

function idOf(item: unknown): string {
  return typeof item === "string" ? item : JSON.stringify(item);
}

export async function ids(client: Client, args: { values: unknown[] }): Promise<string[]> {
  return args.values.map(idOf);
}

/** The canonical similarity from Elasticsearch's _score (DenseVectorFieldMapper.VectorSimilarity.score). */
function similarity(score: number, form: Form): number {
  switch (form.kind) {
    case "relevance":
    case "native":
      return score;
    case "cosine":
    case "dot_product":
      return 2 * score - 1;
    case "max_inner_product":
      return score >= 1 ? score - 1 : 1 - 1 / score;
    case "l2_norm":
      return -Math.sqrt(Math.max(1 / score - 1, 0));
    case "l1_norm":
      return -(1 / score - 1);
    case "hamming":
      return -((form.dims ?? 0) * (1 - score));
    case "byte_dot_product":
      return (score - 0.5) * (form.dims ?? 0) * 32768;
    default:
      throw new Error(`unknown score form ${form.kind}`);
  }
}

function within(score: number, bounds?: Bounds | null): boolean {
  if (!bounds) {
    return true;
  }
  return (bounds.min == null || score >= bounds.min - 1e-9) && (bounds.max == null || score <= bounds.max + 1e-9);
}

function record(hit: Hit, key: string, form?: Form | null): Doc {
  const source = hit._source ?? {};
  const result: Doc = { [key]: key in source ? source[key] : hit._id };
  if (form) {
    result.score = similarity(hit._score, form);
  }
  for (const [name, item] of Object.entries(source)) {
    if (name !== key) {
      result[name] = item;
    }
  }
  if (hit.highlight !== undefined) {
    result.highlight = hit.highlight;
  }
  if (hit._explanation !== undefined) {
    result.explanation = hit._explanation;
  }
  return result;
}

function records(hits: Hit[], key: string, form?: Form | null, bounds?: Bounds | null): Doc[] {
  return hits.map((hit) => record(hit, key, form)).filter((item) => !form || within(item.score as number, bounds));
}

export interface SearchArgs {
  index: string;
  body: Doc;
  key: string;
  score?: Form;
  bounds?: Bounds;
  group?: string;
  params?: Record<string, unknown>;
  after?: unknown;
}

/** A _search answer; a sliced search runs in a point in time opened for it (slicing needs a scroll or a point in time). */
async function answerOf(client: Client, index: string, body: Doc, params?: Record<string, unknown>): Promise<any> {
  if (!("slice" in body)) {
    return send(client, "POST", `/${index}/_search`, params, body);
  }
  const pit = (await send(client, "POST", `/${index}/_pit`, { keep_alive: KEEP_ALIVE })).id as string;
  try {
    return await send(client, "POST", "/_search", params, { ...body, pit: { id: pit, keep_alive: KEEP_ALIVE } });
  } finally {
    await send(client, "DELETE", "/_pit", undefined, { id: pit }, [404]);
  }
}

/** search_after values of a cursor: the score the search gives the cursor record, then its key; null if it does not match. */
async function afterOf(client: Client, index: string, body: Doc, after: unknown): Promise<unknown[] | null> {
  const probe = { query: { bool: { must: [body.query], filter: [{ ids: { values: [idOf(after)] } }] } }, size: 1, _source: false };
  const hits: Hit[] = (await send(client, "POST", `/${index}/_search`, undefined, probe)).hits.hits;
  return hits.length > 0 ? [hits[0]._score, after] : null;
}

/**
 * A _search request; the hits as records, grouped by the collapse field, with the total and aggregations when asked. A cursor
 * (after) continues after that record in the order of the search; a cursor the search does not match gives no hits.
 */
export async function search(client: Client, args: SearchArgs): Promise<Json> {
  let body = args.body;
  if (args.after !== undefined && args.after !== null) {
    const values = await afterOf(client, args.index, body, args.after);
    body = values === null ? { ...body, size: 0 } : { ...body, search_after: values };
  }
  const answer = await answerOf(client, args.index, body, args.params);
  const hits: Hit[] = answer.hits.hits;
  let result: Json = args.group === undefined
    ? records(hits, args.key, args.score, args.bounds)
    : hits.map((hit) => ({ group: hit.fields![args.group!][0], hits: records(hit.inner_hits!.group.hits.hits, args.key, args.score, args.bounds) }));
  if (body.track_total_hits || "aggs" in body) {
    const shaped: Doc = { hits: result };
    if (body.track_total_hits) {
      shaped.total = answer.hits.total.value;
    }
    if ("aggs" in body) {
      shaped.aggregations = answer.aggregations;
    }
    result = shaped;
  }
  return value(result);
}

/**
 * Records by key through _mget, in the order of the keys; missing keys are skipped. Within a tenant, namespace or partition
 * (filters), an ids query with the slice filter.
 */
export async function fetch(client: Client, args: { index: string; values: unknown[]; key: string; fields?: string[]; vectors?: boolean; filters?: Doc[] }): Promise<Json> {
  if (args.filters !== undefined && args.filters.length > 0) {
    const source: Doc = { exclude_vectors: !(args.vectors ?? false) };
    if (args.fields !== undefined) {
      source.includes = [args.key, ...args.fields];
    }
    const wanted = args.values.map(idOf);
    const body = { query: { bool: { filter: [{ ids: { values: wanted } }, ...args.filters] } }, size: wanted.length, _source: source };
    const found = new Map(((await send(client, "POST", `/${args.index}/_search`, undefined, body)).hits.hits as Hit[]).map((hit) => [hit._id, hit]));
    return value(wanted.filter((id) => found.has(id)).map((id) => record(found.get(id)!, args.key, null)));
  }
  const params: Record<string, unknown> = { _source_exclude_vectors: !(args.vectors ?? false) };
  if (args.fields !== undefined) {
    params._source_includes = [args.key, ...args.fields].join(",");
  }
  const answer = await send(client, "POST", `/${args.index}/_mget`, params, { ids: args.values.map(idOf) });
  return value((answer.docs as Hit[]).filter((doc) => doc.found).map((doc) => record(doc, args.key, null)));
}

export interface WriteArgs {
  index: string;
  records: Doc[];
  key: string;
  op: string;
  counter: string;
  extra?: Doc;
  defaults?: Doc;
  batch_size?: number;
  ignore_conflicts?: boolean;
  only?: unknown[];
}

/**
 * Records written with one _bulk request per batch: create (insert), index (replace), update (merge, created when missing) or
 * patch (merge into existing documents only; a missing document is not counted). With only, the records whose key is not
 * among those keys are left out.
 */
export async function write(client: Client, args: WriteArgs): Promise<Json> {
  const size = args.batch_size ?? BATCH;
  const action = args.op === "patch" ? "update" : args.op;
  const keys = args.only === undefined ? null : new Set(args.only.map(idOf));
  const rows = keys === null ? args.records : args.records.filter((item) => args.key in item && keys.has(idOf(item[args.key])));
  let written = 0;
  let skipped = 0;
  for (let start = 0; start < rows.length; start += size) {
    const lines: Doc[] = [];
    for (const item of rows.slice(start, start + size)) {
      if (!(args.key in item)) {
        throw new ElasticsearchFailure(`a record without the key ${args.key}: ${JSON.stringify(item).slice(0, 200)}`);
      }
      const source = { ...(args.defaults ?? {}), ...item, ...(args.extra ?? {}) };
      lines.push({ [action]: { _index: args.index, _id: idOf(item[args.key]) } });
      lines.push(args.op === "update" ? { doc: source, doc_as_upsert: true } : args.op === "patch" ? { doc: source } : source);
    }
    const answer = await send(client, "POST", "/_bulk", { refresh: "true" }, lines, [], true);
    for (const entry of answer.items as Record<string, { status?: number; _id?: string; error?: unknown }>[]) {
      const outcome = entry[action];
      const status = outcome.status ?? 500;
      if (status < 300) {
        written += 1;
      } else if ((args.op === "create" && status === 409) || (args.op === "patch" && status === 404)) {
        skipped += 1;
      } else {
        throw new ElasticsearchFailure(`bulk ${args.op} of ${outcome._id} failed with status ${status}: ${reason({ error: outcome.error })}`);
      }
    }
  }
  if (skipped > 0 && !args.ignore_conflicts && args.op !== "patch") {
    throw new ElasticsearchFailure(`${skipped} records of the insert into ${args.index} already exist`);
  }
  return args.ignore_conflicts ? { [args.counter]: written, skipped } : { [args.counter]: written };
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Doc[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = readFileSync(path, "utf-8");
  const stripped = text.trimStart();
  if (stripped.startsWith("[")) {
    return JSON.parse(stripped) as Doc[];
  }
  return text.split(/\r?\n/).filter((line) => line.trim() !== "").map((line) => JSON.parse(line) as Doc);
}

export async function importFile(client: Client, args: Omit<WriteArgs, "records"> & { location: string }): Promise<Json> {
  return write(client, { ...args, records: await readRecords(client, { location: args.location }) });
}

/** An update applied only while the document's sequence number is seq_no (optimistic concurrency control). */
export async function updateIfVersion(client: Client, args: { index: string; value: unknown; seq_no: number; body: Doc }): Promise<Json> {
  const id = encodeURIComponent(idOf(args.value));
  const current = await send(client, "GET", `/${args.index}/_doc/${id}`, { _source: "false" }, undefined, [404]);
  if (current === null || !current.found) {
    return { update_count: 0 };
  }
  const params = { if_seq_no: args.seq_no, if_primary_term: current._primary_term, refresh: "true" };
  const updated = await send(client, "POST", `/${args.index}/_update/${id}`, params, args.body, [409]);
  return { update_count: updated === null || updated.result === "noop" ? 0 : 1 };
}

/** Deletes the indices a wildcard names; destructive actions take explicit names (action.destructive_requires_name). */
export async function dropMatching(client: Client, args: { pattern: string }): Promise<null> {
  const rows: { index: string }[] = await send(client, "GET", `/_cat/indices/${args.pattern}`, { format: "json", h: "index", expand_wildcards: "all" });
  const names = (rows ?? []).map((row) => row.index).sort();
  if (names.length > 0) {
    await send(client, "DELETE", "/" + names.join(","));
  }
  return null;
}

export interface NamesArgs {
  kind: string;
  path: string;
  body?: Json;
  strip?: string;
  prefix?: string;
  limit?: number;
  ignore?: number[];
}

/** Names read from an answer: indices, database prefixes, aliases, terms of a field, vector fields or snapshots. */
export async function names(client: Client, args: NamesArgs): Promise<string[]> {
  const listing = args.kind === "indices" || args.kind === "databases";
  const answer = await send(client, args.body !== undefined ? "POST" : "GET", args.path, listing ? { format: "json" } : undefined, args.body,
    args.ignore ?? []);
  let found: string[] = [];
  if (answer === null || answer === undefined) {
    found = [];
  } else if (args.kind === "indices") {
    found = (answer as { index: string }[]).map((row) => row.index);
  } else if (args.kind === "databases") {
    found = (answer as { index: string }[]).filter((row) => row.index.replace(/^\.+/, "").includes(".")).map((row) => row.index.split(".")[0]);
  } else if (args.kind === "aliases") {
    found = Object.values(answer as Record<string, { aliases?: Doc }>).flatMap((entry) => Object.keys(entry.aliases ?? {}));
  } else if (args.kind === "terms") {
    found = (answer.aggregations.names.buckets as { key: unknown }[]).map((bucket) => String(bucket.key));
  } else if (args.kind === "vector_fields") {
    found = Object.values(answer as Record<string, { mappings: { properties?: Record<string, { type?: string }> } }>).flatMap((entry) =>
      Object.entries(entry.mappings.properties ?? {}).filter(([, field]) => field.type === "dense_vector" || field.type === "sparse_vector").map(([name]) => name));
  } else if (args.kind === "snapshots") {
    found = ((answer.snapshots ?? []) as { snapshot: string }[]).map((snapshot) => snapshot.snapshot);
  }
  let result = [...new Set(found.filter((name) => !name.startsWith(".")).map((name) => (args.strip && name.startsWith(args.strip) ? name.slice(args.strip.length) : name)))].sort();
  if (args.prefix !== undefined) {
    result = result.filter((name) => name.startsWith(args.prefix!));
  }
  return args.limit === undefined ? result : result.slice(0, args.limit);
}

/** The health of an index once it reaches status, or a clear error after timeoutSeconds. */
export async function waitHealth(client: Client, args: { index: string; status: string; timeout_seconds: number }): Promise<Json> {
  const answer = await send(client, "GET", `/_cluster/health/${args.index}`, { wait_for_status: args.status, timeout: `${args.timeout_seconds}s` },
    undefined, [408]);
  if (answer === null || answer.timed_out) {
    throw new Error(`index ${args.index} did not reach health ${args.status} within ${args.timeout_seconds} seconds`);
  }
  return answer.status;
}

async function vectors(client: Client, index: string, field: string, values: unknown[]): Promise<number[][]> {
  if (values.length === 0) {
    return [];
  }
  const answer = await send(client, "POST", `/${index}/_mget`, { _source_includes: field, _source_exclude_vectors: false }, { ids: values.map(idOf) });
  const found = (answer.docs as Hit[]).filter((doc) => doc.found && doc._source && field in doc._source).map((doc) => doc._source![field] as number[]);
  if (found.length !== values.length) {
    throw new ElasticsearchFailure(`a record of ${index} named by the statement has no ${field} vector`);
  }
  return found;
}

function average(rows: number[][]): number[] {
  return rows[0].map((_, column) => rows.reduce((sum, row) => sum + row[column], 0) / rows.length);
}

export interface RecommendArgs {
  index: string;
  lookup: string;
  field: string;
  key: string;
  body: Doc;
  score: Form;
  positive_ids?: unknown[];
  positive_vectors?: number[][];
  negative_ids?: unknown[];
  negative_vectors?: number[][];
  bounds?: Bounds;
  group?: string;
  after?: unknown;
}

/** The body with the computed vector in every query_vector the generator left empty. */
function withVector(item: unknown, vector: number[]): unknown {
  if (Array.isArray(item)) {
    return item.map((entry) => withVector(entry, vector));
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item as Doc).map(([name, entry]) => [name, name === "query_vector" && entry === null ? vector : withVector(entry, vector)]));
  }
  return item;
}

/** Qdrant's average-vector strategy: avg(positive) + (avg(positive) - avg(negative)) as the query vector of the search. */
export async function recommend(client: Client, args: RecommendArgs): Promise<Json> {
  const positives = [...(await vectors(client, args.lookup, args.field, args.positive_ids ?? [])), ...(args.positive_vectors ?? [])];
  const negatives = [...(await vectors(client, args.lookup, args.field, args.negative_ids ?? [])), ...(args.negative_vectors ?? [])];
  let query = average(positives);
  if (negatives.length > 0) {
    const avoid = average(negatives);
    query = query.map((item, index) => 2 * item - avoid[index]);
  }
  return search(client, { index: args.index, body: withVector(args.body, query) as Doc, key: args.key, score: args.score, bounds: args.bounds, group: args.group, after: args.after });
}

function compare(a: Doc, b: Doc, key: string): number {
  const difference = (b.score as number) - (a.score as number);
  if (difference !== 0) {
    return difference;
  }
  const x = a[key];
  const y = b[key];
  if (typeof x === "number" && typeof y === "number") {
    return x - y;
  }
  if (typeof x === "number") {
    return -1;
  }
  if (typeof y === "number") {
    return 1;
  }
  return String(x) < String(y) ? -1 : String(x) > String(y) ? 1 : 0;
}

export interface HybridArgs {
  index: string;
  legs: { body: Doc; score: Form; weight: number }[];
  fusion: string;
  k: number;
  size: number;
  offset: number;
  key: string;
  bounds?: Bounds;
  group?: string;
  group_size?: number;
  after?: unknown;
  mmr?: Mmr;
  sort?: Doc[];
  total?: boolean;
  aggs?: Doc;
}

/** The canonical similarity between two stored vectors of a field with that similarity. */
function canonical(a: number[], b: number[], kind: string): number {
  switch (kind) {
    case "cosine": {
      const norm = Math.sqrt(a.reduce((sum, x) => sum + x * x, 0)) * Math.sqrt(b.reduce((sum, y) => sum + y * y, 0));
      return norm !== 0 ? a.reduce((sum, x, i) => sum + x * b[i], 0) / norm : 0;
    }
    case "dot_product":
    case "max_inner_product":
      return a.reduce((sum, x, i) => sum + x * b[i], 0);
    case "l2_norm":
      return -Math.sqrt(a.reduce((sum, x, i) => sum + (x - b[i]) ** 2, 0));
    case "l1_norm":
      return -a.reduce((sum, x, i) => sum + Math.abs(x - b[i]), 0);
    default:
      throw new Error(`no similarity for ${kind}`);
  }
}

/**
 * Maximal marginal relevance over the first window records: lambda * score - (1 - lambda) * the highest similarity to a record
 * already picked, in pick order; each record keeps its own score.
 */
async function diverse(client: Client, index: string, ranked: Doc[], key: string, mmr: Mmr, count: number): Promise<Doc[]> {
  const pool = ranked.slice(0, mmr.window);
  const stored = await vectors(client, index, mmr.field, pool.map((item) => item[key]));
  const rest = pool.map((_, i) => i);
  const picked: number[] = [];
  while (rest.length > 0 && picked.length < count) {
    const worth = (i: number): number => {
      const penalty = picked.length === 0 ? 0 : Math.max(...picked.map((j) => canonical(stored[i], stored[j], mmr.kind)));
      return mmr.lambda * (pool[i].score as number) - (1 - mmr.lambda) * penalty;
    };
    let best = rest[0];
    for (const i of rest) {
      if (worth(i) > worth(best)) {
        best = i;
      }
    }
    picked.push(best);
    rest.splice(rest.indexOf(best), 1);
  }
  return picked.map((i) => pool[i]);
}

/** The records of a page in the order of the sort clauses, as the server sorts them. */
async function ordered(client: Client, index: string, page: Doc[], key: string, sort: Doc[]): Promise<Doc[]> {
  if (page.length === 0) {
    return page;
  }
  const byId = new Map(page.map((item) => [idOf(item[key]), item]));
  const body = { query: { ids: { values: [...byId.keys()] } }, sort, size: byId.size, _source: false };
  return ((await send(client, "POST", `/${index}/_search`, undefined, body)).hits.hits as Hit[]).map((hit) => byId.get(hit._id)!);
}

/**
 * Fusion of the legs' hits: rrf sums 1/(k + rank), weighted sums weight * similarity, relative_score sums the weighted
 * min-max normalized similarities; ties by key. The fused records within the bounds are the result set: groups by the group
 * field's value, a page after the cursor record, maximal marginal relevance, the server's order of the sort clauses on the
 * page, the total and the aggregations of the set (an ids query).
 */
export async function hybrid(client: Client, args: HybridArgs): Promise<Json> {
  const fused = new Map<string, Doc>();
  const groups = new Map<string, unknown>();
  for (const [position, leg] of args.legs.entries()) {
    const hits: Hit[] = (await send(client, "POST", `/${args.index}/_search`, undefined, leg.body)).hits.hits;
    const found = hits.map((hit) => record(hit, args.key, leg.score));
    const scores = found.map((item) => item.score as number);
    const low = scores.length > 0 ? Math.min(...scores) : 0;
    const high = scores.length > 0 ? Math.max(...scores) : 0;
    found.forEach((item, rank) => {
      const score = item.score as number;
      const part = args.fusion === "rrf" ? 1 / (args.k + rank + 1)
        : args.fusion === "relative_score" ? leg.weight * (high > low ? (score - low) / (high - low) : 1)
          : leg.weight * score;
      const id = idOf(item[args.key]);
      if (!fused.has(id)) {
        const entry: Doc = {};
        for (const [name, field] of Object.entries(item)) {
          if (name !== "score" && name !== "highlight" && name !== "explanation") {
            entry[name] = field;
          }
        }
        entry.score = 0;
        fused.set(id, entry);
      }
      const entry = fused.get(id)!;
      entry.score = (entry.score as number) + part;
      if ("highlight" in item && !("highlight" in entry)) {
        entry.highlight = item.highlight;
      }
      if ("explanation" in item) {
        if (!("explanation" in entry)) {
          entry.explanation = args.legs.map(() => null);
        }
        (entry.explanation as unknown[])[position] = item.explanation;
      }
      if (args.group !== undefined && !groups.has(id)) {
        groups.set(id, hits[rank].fields?.[args.group]?.[0] ?? null);
      }
    });
  }
  const ranked = [...fused.values()].filter((item) => within(item.score as number, args.bounds)).sort((a, b) => compare(a, b, args.key));
  let result: Json;
  if (args.group !== undefined) {
    const members = new Map<unknown, Doc[]>();
    for (const item of ranked) {
      const group = groups.get(idOf(item[args.key]));
      if (!members.has(group)) {
        members.set(group, []);
      }
      members.get(group)!.push(item);
    }
    result = [...members.entries()].slice(args.offset, args.offset + args.size).map(([group, hits]) => ({ group, hits: hits.slice(0, args.group_size ?? 1) }));
  } else if (args.mmr !== undefined) {
    result = (await diverse(client, args.index, ranked, args.key, args.mmr, args.offset + args.size)).slice(args.offset);
  } else {
    let start = args.offset;
    if (args.after !== undefined && args.after !== null) {
      const position = ranked.findIndex((item) => idOf(item[args.key]) === idOf(args.after));
      start = position < 0 ? ranked.length : position + 1;
    }
    result = ranked.slice(start, start + args.size);
  }
  if (args.sort !== undefined && args.sort.length > 0) {
    result = await ordered(client, args.index, result as Doc[], args.key, args.sort);
  }
  if (args.total || args.aggs !== undefined) {
    const shaped: Doc = { hits: result };
    if (args.total) {
      shaped.total = ranked.length;
    }
    if (args.aggs !== undefined) {
      const body = { size: 0, query: { ids: { values: ranked.map((item) => idOf(item[args.key])) } }, aggs: args.aggs };
      shaped.aggregations = (await send(client, "POST", `/${args.index}/_search`, undefined, body)).aggregations;
    }
    result = shaped;
  }
  return value(result);
}

/** Qdrant's definition: a random sample of the matching documents, each with its nearest neighbours in the sample. */
export async function distanceMatrix(client: Client, args: { index: string; field: string; key: string; sample: number; limit: number; score: Form; query: Doc }): Promise<Json> {
  const body = {
    size: args.sample, _source: { includes: [args.key, args.field], exclude_vectors: false },
    query: { function_score: { query: args.query, random_score: { seed: Math.floor(Math.random() * 2 ** 30), field: "_seq_no" } } },
  };
  const docs = (await send(client, "POST", `/${args.index}/_search`, undefined, body)).hits.hits as Hit[];
  const members = docs.map((doc) => doc._id);
  const result: Doc[] = [];
  for (const doc of docs) {
    const others = members.filter((member) => member !== doc._id);
    let hits: Hit[] = [];
    if (others.length > 0) {
      const knn = { field: args.field, query_vector: doc._source![args.field], k: Math.max(1, Math.min(args.limit, others.length)),
        num_candidates: Math.max(args.limit, others.length, 1), filter: { ids: { values: others } } };
      hits = (await send(client, "POST", `/${args.index}/_search`, undefined, { size: args.limit, knn, _source: [args.key] })).hits.hits;
    }
    result.push({ id: doc._source?.[args.key] ?? doc._id,
      neighbours: hits.map((hit) => ({ id: hit._source?.[args.key] ?? hit._id, score: similarity(hit._score, args.score) })) });
  }
  return value(result);
}
